// Score pages by missed clicks against a position-based CTR benchmark.
const cfg = $('Configure Workflow Settings').first().json;

// Skip pages logged within the cooldown window
const cooldownMs = Number(cfg.cooldown_days) * 86400000;
const now = Date.now();
const recent = new Set();
for (const row of $('Read SEO Log From Sheets').all()) {
  const url = String(row.json.page_url ?? '').trim();
  if (!url) continue;
  const t = Date.parse(row.json.updated_at);
  if (isNaN(t) || now - t < cooldownMs) recent.add(url);
}

// Rough industry CTR benchmark by average position (1-10).
// Replace with your own site's averages for better accuracy.
const curve = [0.28, 0.16, 0.11, 0.08, 0.06, 0.05, 0.04, 0.035, 0.03, 0.025];
const expectedCtr = (pos) => {
  if (pos <= 10) return curve[Math.max(1, Math.round(pos)) - 1];
  if (pos <= 20) return 0.01;
  return 0.005;
};

const base = new URL(cfg.wp_base_url).hostname.replace(/^www\./, '');
const rows = $('Post Performance Data from GSC').first().json.rows ?? [];

const candidates = [];
for (const r of rows) {
  const pageUrl = r.keys[0];
  let parsed;
  try { parsed = new URL(pageUrl); } catch { continue; }
  if (parsed.hostname.replace(/^www\./, '') !== base) continue;
  if (parsed.hash || parsed.search) continue;

  const segments = parsed.pathname.split('/').filter(Boolean);
  if (segments.length === 0) continue; // skip the home page
  if (recent.has(pageUrl)) continue;
  if (r.impressions < cfg.min_impressions || r.position > cfg.max_position) continue;

  const expected = expectedCtr(r.position);
  if (r.ctr >= expected * cfg.ctr_ratio) continue;

  candidates.push({
    page_url: pageUrl,
    path: decodeURIComponent(parsed.pathname).replace(/\/+$/, '').toLowerCase(),
    slug: decodeURIComponent(segments[segments.length - 1]),
    impressions: r.impressions,
    clicks: r.clicks,
    ctr: Number(r.ctr.toFixed(4)),
    position: Number(r.position.toFixed(1)),
    expected_ctr: expected,
    missed_clicks: Math.round(r.impressions * (expected - r.ctr)),
  });
}

candidates.sort((a, b) => b.missed_clicks - a.missed_clicks);
return candidates
  .slice(0, Number(cfg.max_per_run))
  .map((json) => ({ json, pairedItem: { item: 0 } }));

// Match candidate pages to WordPress posts/pages by URL path.
const normalize = (u) => {
  try { return decodeURIComponent(new URL(u).pathname).replace(/\/+$/, '').toLowerCase(); }
  catch { return ''; }
};

const index = {};
for (const [node, restBase] of [['Retrieve WordPress Posts by Slug', 'posts'], ['Retrieve WordPress Pages by Slug', 'pages']]) {
  for (const item of $(node).all()) {
    const j = item.json;
    if (!j || j.error || !j.id || !j.link) continue;
    index[normalize(j.link)] = { wp_id: j.id, wp_type: restBase };
  }
}

return $('Calculate Underperformance Score').all().map((item, i) => {
  const match = index[item.json.path] ?? { wp_id: '', wp_type: '' };
  return { json: { ...item.json, ...match }, pairedItem: { item: i } };
});

